SELECT '1. ensure_trip_share_slug(uuid) 存在且指紋＝6743b0826daf26406875603a277a41d4（正式庫套用前）' AS item, (SELECT md5(replace(p.prosrc, E'\r', '')) = '6743b0826daf26406875603a277a41d4' FROM pg_proc p WHERE p.oid = to_regprocedure('public.ensure_trip_share_slug(uuid)')) AS ok
UNION ALL SELECT '2. ensure_trip_share_slug 的 BEGIN 錨點（換行＋BEGIN＋換行）剛好出現 1 次', (SELECT (length(replace(p.prosrc, E'\r', '')) - length(replace(replace(p.prosrc, E'\r', ''), E'\nBEGIN\n', ''))) / 7 = 1 FROM pg_proc p WHERE p.oid = to_regprocedure('public.ensure_trip_share_slug(uuid)'))
UNION ALL SELECT '3. ensure_trip_share_slug 尚未含 TRIP_OWNER_GUARD_V1', (SELECT position('TRIP_OWNER_GUARD_V1' IN p.prosrc) = 0 FROM pg_proc p WHERE p.oid = to_regprocedure('public.ensure_trip_share_slug(uuid)'))
UNION ALL SELECT '4. ensure_trip_share_slug 屬性：SECURITY DEFINER、plpgsql、RETURNS text、search_path=public', (SELECT p.prosecdef AND l.lanname = 'plpgsql' AND p.prorettype = 'text'::regtype AND p.proconfig = ARRAY['search_path=public'] FROM pg_proc p JOIN pg_language l ON l.oid = p.prolang WHERE p.oid = to_regprocedure('public.ensure_trip_share_slug(uuid)'))
UNION ALL SELECT '5. trips 擁有者欄位 owner_id 為 uuid', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'trips' AND column_name = 'owner_id' AND data_type = 'uuid')
UNION ALL SELECT '6. ensure_trip_share_slug 授權：PUBLIC、anon、authenticated、service_role 皆可執行（正式庫原狀）', (SELECT has_function_privilege('anon', p.oid, 'EXECUTE') AND has_function_privilege('authenticated', p.oid, 'EXECUTE') AND has_function_privilege('service_role', p.oid, 'EXECUTE') AND EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 0) FROM pg_proc p WHERE p.oid = to_regprocedure('public.ensure_trip_share_slug(uuid)'))
UNION ALL SELECT '7. _hotelnabe_enqueue_days 指紋＝8e9c59faaf944996252177d8a0071ab6', (SELECT md5(replace(p.prosrc, E'\r', '')) = '8e9c59faaf944996252177d8a0071ab6' FROM pg_proc p WHERE p.oid = to_regprocedure('public._hotelnabe_enqueue_days(uuid, uuid, date, date, public.hotelnabe_ari_push_reason)'))
UNION ALL SELECT '8. _hotelnabe_enqueue_days 授權：authenticated、service_role 可；anon 不可；無 PUBLIC（正式庫原狀）', (SELECT NOT has_function_privilege('anon', p.oid, 'EXECUTE') AND has_function_privilege('authenticated', p.oid, 'EXECUTE') AND has_function_privilege('service_role', p.oid, 'EXECUTE') AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 0) FROM pg_proc p WHERE p.oid = to_regprocedure('public._hotelnabe_enqueue_days(uuid, uuid, date, date, public.hotelnabe_ari_push_reason)'))
UNION ALL SELECT '9. 呼叫 _hotelnabe_enqueue_days 的函式只有 3 支觸發器函式，且全部 SECURITY DEFINER', (SELECT count(*) = 3 AND bool_and(p.prosecdef) AND bool_and(p.proname IN ('fn_hotelnabe_enqueue_from_order', 'fn_hotelnabe_enqueue_from_order_rooms', 'fn_hotelnabe_enqueue_from_rip')) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname <> '_hotelnabe_enqueue_days' AND p.prosrc ~ '\m_hotelnabe_enqueue_days\M')
UNION ALL SELECT '10. 沒有 RLS policy 引用 ensure_trip_share_slug／_hotelnabe_enqueue_days', NOT EXISTS (SELECT 1 FROM pg_policy pol WHERE COALESCE(pg_get_expr(pol.polqual, pol.polrelid), '') || ' ' || COALESCE(pg_get_expr(pol.polwithcheck, pol.polrelid), '') ~ '(ensure_trip_share_slug|_hotelnabe_enqueue_days)');

SELECT p.oid::regprocedure::text AS func, COALESCE(p.proacl::text, 'NULL') AS proacl, md5(replace(p.prosrc, E'\r', '')) AS fp, p.prosecdef AS secdef, p.proconfig::text AS config
FROM pg_proc p
WHERE p.oid IN (to_regprocedure('public.ensure_trip_share_slug(uuid)'), to_regprocedure('public._hotelnabe_enqueue_days(uuid, uuid, date, date, public.hotelnabe_ari_push_reason)'))
ORDER BY 1;
